import{_ as e,a as r,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"制品标识、发布与回滚","description":"版本、清单、摘要、同一制品晋级、回滚前提与保留策略。","frontmatter":{"title":"制品标识、发布与回滚","description":"版本、清单、摘要、同一制品晋级、回滚前提与保留策略。","showdocs":{"topics":[{"id":"release","title":"发布与制品管理","link":"/topics/release/"}],"kind":"发布与制品管理上手与对象","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"发布与制品管理：版本、清单与回滚资料","summary":"版本、清单、摘要、同一制品晋级、回滚前提与保留策略。","status":"active","related":[{"title":"发布与制品管理：完整实践与解答","link":"/tools/collaboration-delivery/release/practice/application","kind":"发布与制品管理完整实践与解答","scope":"general","audience":"general"}],"prev":false,"next":{"text":"发布与制品管理：完整实践与解答","link":"/tools/collaboration-delivery/release/practice/application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"发布与制品管理：完整实践与解答","link":"/tools/collaboration-delivery/release/practice/application"}},"headers":[],"relativePath":"tools/collaboration-delivery/release/artifact-lifecycle.md","filePath":"tools/collaboration-delivery/release/artifact-lifecycle.md"}'),l={name:"tools/collaboration-delivery/release/artifact-lifecycle.md"};function i(n,a,p,s,c,h){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="制品标识、发布与回滚" tabindex="-1">制品标识、发布与回滚 <a class="header-anchor" href="#制品标识、发布与回滚" aria-label="Permalink to &quot;制品标识、发布与回滚&quot;">​</a></h1><h2 id="part-1" tabindex="-1">关联版本、内容摘要与清单 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;关联版本、内容摘要与清单 {#part-1}&quot;">​</a></h2><p>需能阅读文件清单和摘要。<a href="/tools/collaboration-delivery/release/practice/application#source">本地制品示例</a>用 Python 3.11+ 标准库与 zlib，把 <code>payload/README.txt</code> 打成 ZIP，并记录字节数与 SHA-256；输出目录必须全新。本页解释标识、晋级和回滚前提，示例只打包、不发布。 示例未在本轮执行。</p><h3 id="part-1-identity" tabindex="-1">制品 唯一标识 <a class="header-anchor" href="#part-1-identity" aria-label="Permalink to &quot;制品 唯一标识 {#part-1-identity}&quot;">​</a></h3><p>制品唯一标识要关联源码提交和构建输入。相同版本号不能被静默替换不同字节；文件名便于人读，摘要用于核对实际内容，二者解决不同问题。</p><h3 id="part-1-semver" tabindex="-1">发布 语义版本 <a class="header-anchor" href="#part-1-semver" aria-label="Permalink to &quot;发布 语义版本 {#part-1-semver}&quot;">​</a></h3><p>发布语义版本以公开API为前提：主版本表达不兼容，次版本表达兼容新增，补丁表达兼容修复。预发布标识表示尚未稳定的版本，不能仅凭版本号承诺数据库迁移可逆。</p><h3 id="part-1-manifest" tabindex="-1">制品 清单 <a class="header-anchor" href="#part-1-manifest" aria-label="Permalink to &quot;制品 清单 {#part-1-manifest}&quot;">​</a></h3><p>制品清单列出文件名、字节数、SHA-256和来源说明。摘要验证内容一致性，不能证明来源可信；签名需要单独的信任根与密钥管理，本例不生成或宣称签名。</p><p><span id="part-3-sources"></span></p><p><span id="part-2-sources"></span></p><h3 id="part-1-sources" tabindex="-1">依据与适用范围 <a class="header-anchor" href="#part-1-sources" aria-label="Permalink to &quot;依据与适用范围 {#part-1-sources}&quot;">​</a></h3><ul><li><a href="https://semver.org/lang/zh-CN/" target="_blank" rel="noopener noreferrer">本课官方依据</a>，资料核对日2026-10-17。</li></ul><p>以上依据用于解释本文列明的规则；示例未执行，不代表产品全部能力或跨平台验证。历史资料的版本、账号与界面位置需按目标环境确认。</p><h2 id="part-2" tabindex="-1">编写发布说明并确认回滚前提 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;编写发布说明并确认回滚前提 {#part-2}&quot;">​</a></h2><h3 id="part-2-notes" tabindex="-1">发布 变更说明 <a class="header-anchor" href="#part-2-notes" aria-label="Permalink to &quot;发布 变更说明 {#part-2-notes}&quot;">​</a></h3><p>发布变更说明按使用者影响组织新增、修复、不兼容和迁移步骤。关联提交可追溯实现，但提交日志不等于发布说明；明确需要用户操作的配置变更和数据兼容边界。</p><h3 id="part-2-promotion" tabindex="-1">制品 环境晋级 <a class="header-anchor" href="#part-2-promotion" aria-label="Permalink to &quot;制品 环境晋级 {#part-2-promotion}&quot;">​</a></h3><p>制品环境晋级应移动同一不可变制品，环境配置单独注入。每个环境重新构建会让已验收字节与上线字节不同；记录晋级审批和目标，不在本课执行部署。</p><h3 id="part-2-rollback" tabindex="-1">发布 回滚前置 <a class="header-anchor" href="#part-2-rollback" aria-label="Permalink to &quot;发布 回滚前置 {#part-2-rollback}&quot;">​</a></h3><p>发布回滚前置包括旧制品可取、配置兼容和数据向后兼容。恢复二进制不自动恢复数据；迁移删除字段后旧程序可能无法读取，应先采用扩展再收缩或准备独立恢复方案。</p><h2 id="part-3" tabindex="-1">检查摘要、版本排序与保留范围 <a class="header-anchor" href="#part-3" aria-label="Permalink to &quot;检查摘要、版本排序与保留范围 {#part-3}&quot;">​</a></h2><h3 id="part-3-mismatch" tabindex="-1">制品 校验不符 <a class="header-anchor" href="#part-3-mismatch" aria-label="Permalink to &quot;制品 校验不符 {#part-3-mismatch}&quot;">​</a></h3><p>制品校验不符先停止使用并对比下载来源、摘要算法和文件字节。换行、压缩元数据或截断都可能改变摘要；重新计算并不能证明哪个来源正确，需要回到可信清单。</p><h3 id="part-3-prerelease" tabindex="-1">发布 预发布排序 <a class="header-anchor" href="#part-3-prerelease" aria-label="Permalink to &quot;发布 预发布排序 {#part-3-prerelease}&quot;">​</a></h3><p>发布预发布排序按SemVer规则比较点分标识，数字标识按数值比较。1.0.0-rc.2低于1.0.0-rc.10，两者都低于1.0.0；不能用普通字符串排序选择稳定版本。</p><h3 id="part-3-retention" tabindex="-1">制品 保留策略 <a class="header-anchor" href="#part-3-retention" aria-label="Permalink to &quot;制品 保留策略 {#part-3-retention}&quot;">​</a></h3><p>制品保留策略由回滚窗口、审计需要和存储成本共同决定。清理前确认部署仍引用哪些摘要，不能只按最新几个文件删除；备份与保留是不同控制，需验证恢复来源。</p>',28)])])}const m=e(l,[["render",i]]);export{u as __pageData,m as default};
